(()=>{
'use strict';
const C=Core,D=DATA,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyphs={bag:'M7 7V5a5 5 0 0 1 10 0v2M5 7h14l2 14H3ZM4 9l8 5 8-5M10 13v4h4v-4',music:'M9 18V5l12-3v13M9 8l12-3M6 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6M18 12a3 3 0 1 0 0 6 3 3 0 0 0 0-6',play:'m8 4 13 8-13 8Z',pause:'M8 4v16M16 4v16',stop:'M6 6h12v12H6Z',repeat:'m18 2 4 4-4 4M2 11V8a2 2 0 0 1 2-2h18M6 22l-4-4 4-4M22 13v3a2 2 0 0 1-2 2H2',volume:'m11 3-6 5H2v8h3l6 5ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75',search:'m21 21-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',book:'M12 6v15M3 3c4 0 7 1 9 3 2-2 5-3 9-3v15c-4 0-7 1-9 3-2-2-5-3-9-3Z',save:'M5 3h12l4 4v14H3V3ZM7 3v6h10V3M7 21v-8h10v8',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',compass:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M16 8l-3 5-5 3 3-5Z',shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7ZM8 12l3 3 5-6',heart:'M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-4 4 0 8 8 15 8-7 12-11 8-15Z',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',bolt:'m13 2-9 12h7l-1 8 10-13h-8Z',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',settings:'M4 5h16M4 12h16M4 19h16M8 3v4M16 10v4M10 17v4',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',leaf:'M20 3C4 3 1 10 5 17s15 3 15-14ZM4 21l11-12',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',check:'m4 12 5 5L20 6'};
function icon(k){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${glyphs[k]||glyphs.book}"/></svg>`;}
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
let state=C.defaults(),page='characters',subtab='growth',query='',category='',onlyBookmarks=false,detail=null,revealed=new Set(),modal='',draft={},limit=60,loadError='',cardRange='early';
try{const raw=window.Android?Android.load():localStorage.getItem('arydia-v1');if(raw)state=C.validate(JSON.parse(raw));}catch(e){loadError='已有记录未能读取。为避免覆盖，请先导出原始数据后再恢复备份。';}
function persist(){if(loadError)throw Error(loadError);const raw=JSON.stringify(state);if(window.Android){if(!Android.save(raw))throw Error('保存失败，请检查设备剩余空间');}else localStorage.setItem('arydia-v1',raw);}
function change(fn,redraw=true){const old=C.clone(state);try{if(loadError)throw Error(loadError);fn();if(state.webMapSaves)CampaignModel.saveCurrentMap(state);persist();if(redraw)render();return true;}catch(e){state=old;toast(e.message);return false;}}
function active(){return state.characters.find(c=>c.id===state.active)||state.characters[0];}
let seeking=false;let campaignSupportOrigin='';
const navGlyphs={"people": "<svg class=\"camp-nav-svg\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M 5.5 7.5 a 3.5 3.5 0 1 0 7.0 0 a 3.5 3.5 0 1 0 -7.0 0 Z\" fill=\"currentColor\" fill-rule=\"nonzero\" /><path d=\"M1.8 20v-2a7.2 7.2 0 0 1 14.4 0v2a1 1 0 0 1-1 1H2.8a1 1 0 0 1-1-1 M17 4a3.5 3.5 0 0 1 0 7v-1a6 6 0 0 0 0-5Z M17 13a7 7 0 0 1 5.2 6.8A1.2 1.2 0 0 1 21 21h-2.6v-3a10 10 0 0 0-1.4-5\" fill=\"currentColor\" fill-rule=\"nonzero\" /></svg>", "search": "<svg class=\"camp-nav-svg\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M10 2a8 8 0 1 0 4.6 14.5l5 5a1.6 1.6 0 0 0 2.3-2.3l-5-5A8 8 0 0 0 10 2Zm0 3.2a4.8 4.8 0 1 1 0 9.6 4.8 4.8 0 0 1 0-9.6Z\" fill=\"currentColor\" fill-rule=\"evenodd\" /></svg>", "map": "<svg class=\"camp-nav-svg\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M2 6a2 2 0 0 1 1.4-1.9L8 2.5v16L2 21Z M10 2.5l5 2v17l-5-2Z M17 4.5l5-2v16a2 2 0 0 1-1.3 1.9L17 22Z\" fill=\"currentColor\" fill-rule=\"nonzero\" /></svg>", "bag": "<svg class=\"camp-nav-svg\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M8 5a4 4 0 1 1 8 0v1h2a3 3 0 0 1 3 3v10a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V9a3 3 0 0 1 3-3h2Zm2 1h4V5a2 2 0 0 0-4 0Zm-5 4v2l6 2v3h2v-3l6-2v-2l-7 2Z\" fill=\"currentColor\" fill-rule=\"evenodd\" /></svg>", "settings": "<svg class=\"camp-nav-svg\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path d=\"M3 4h18a1.5 1.5 0 0 1 0 3H3a1.5 1.5 0 0 1 0-3 M3 10.5h18a1.5 1.5 0 0 1 0 3H3a1.5 1.5 0 0 1 0-3 M3 17h18a1.5 1.5 0 0 1 0 3H3a1.5 1.5 0 0 1 0-3\" fill=\"currentColor\" fill-rule=\"nonzero\" /><path d=\"M7 2h2v7H7Z M15 8.5h2v7h-2Z M7 15h2v7H7Z\" fill=\"currentColor\" fill-rule=\"nonzero\" /></svg>"};
let timer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function btn(action,label,cls='',data=''){return `<button class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function top(title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">THE PATHS WE DARE TREAD</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>${action}</div>`;}
function syncHeroContour(){const hero=document.querySelector('.traveler:not(.compact-hero)');if(!hero)return;const w=hero.clientWidth,h=hero.clientHeight,r=Math.min(26,h/3),lift=32;const path=`path("M ${r} ${lift} C ${w*.42} ${lift} ${w*.63} 0 ${w-r} 0 Q ${w} 0 ${w} ${r} L ${w} ${h-r} Q ${w} ${h} ${w-r} ${h} L ${r} ${h} Q 0 ${h} 0 ${h-r} L 0 ${lift+r} Q 0 ${lift} ${r} ${lift} Z")`;if(CSS.supports('clip-path',path))hero.style.clipPath=path;}
function render(){
 UI.apply(active()?.race);
 document.body.dataset.searchWorkspace=String(page==='search'&&!detail);
 document.body.dataset.view=page==='characters'&&!active()?'welcome':page;
 $('#nav').innerHTML=[['characters','people','角色卡'],['search','search','检索'],['map','map','地图'],['inventory','bag','团队背包'],['settings','settings','设置']].map(([p,i,t])=>`<button data-action="navigate" data-page="${p}" class="${(page===p||page==='personalInventory'&&p==='characters'||page==='music'&&p==='settings')?'active':''}" aria-current="${page===p?'page':'false'}"><span class="nav-icon">${navGlyphs[i]}</span><span>${t}</span></button>`).join('');
 $('#main').innerHTML=(loadError?`<div class="notice">${esc(loadError)}${btn('rawBackup','导出原始记录','small')}</div>`:'')+(page==='characters'?characters():page==='search'&&detail?detailPage():['search','inventory','personalInventory','map'].includes(page)?Campaign.view(page):page==='music'?musicPage():settings());
 updateMusic();window.WebApp?.mount(page);window.Campaign?.mount(page);UI.localize();requestAnimationFrame(()=>{document.documentElement.style.setProperty('--app-nav-height',$('#nav').getBoundingClientRect().height+'px');syncHeroContour();drawArrows();});
}
const statNames=['生命','法力','体力','力量','敏捷','智力','感知','魅力','耐力'];
const rowColors=['#964f5b','#386d86','#51764e','#9b7049','#4b827b','#80658f','#a08b45','#787a75','#78894c'];
const rowWash=['#f8eff0','#edf3f6','#eef3ed','#f7f1e9','#edf5f2','#f3eff6','#f8f5e9','#f1f2ef','#f3f5ea'];
let cardZoom=1;
function paperCheck(on){return `<span class="replica-check ${on?'checked':''}">${icon('check')}</span>`;}
function growthCell(c,row,col){const r=C.race(c.race),s=C.sheet(c),on=row<0?s.levels[col]:s.marks[row][col],value=row<0?col:row<3?r.stats[row][col]:Math.min(col+1,10),name=row<0?'等级':statNames[row],locked=col>C.cardDerived(c).level+(row<0?1:0)&&!on;return `<td><button class="growth-square ${on?'on':''} ${locked?'is-locked':''}" title="${locked?'达到'+col+'级后可提升此属性':''}" data-action="cardMark" data-row="${row}" data-col="${col}" role="checkbox" aria-checked="${on}" aria-label="${col}级 ${name} ${value}" ${col===0?'disabled':''}><span class="printed-value">${value}</span>${paperCheck(on)}</button>${row<0&&[3,5,8].includes(col)?'<span class="event-print">事件</span>':''}</td>`;}
function replicaToolbar(){return `<div class="replica-toolbar"><span class="card-caption">${subtab==='skills'?'技能树':'成长记录'}</span></div>`;}
function growthView(c){return `${replicaToolbar()}<div class="replica-scroll growth-scroll"><div class="replica-paper" style="width:${cardZoom*100}%"><table class="replica-growth" aria-label="${C.race(c.race).name}成长卡"><colgroup><col class="name-col">${Array(11).fill('<col>').join('')}</colgroup><thead><tr class="xp-print"><th colspan="2" scope="row">经验费用</th>${D.xp.map(n=>`<th scope="col">${n}</th>`).join('')}</tr></thead><tbody><tr class="level-print"><th scope="row">等级</th>${Array.from({length:11},(_,n)=>growthCell(c,-1,n)).join('')}</tr><tr class="replica-separator"><td colspan="12"><span>核心属性 · 每级勾选一项</span><b>${C.race(c.race).name}</b></td></tr>${statNames.map((name,row)=>`${row===3?'<tr class="replica-separator"><td colspan="12"><span>基础属性 · 每级勾选一项</span></td></tr>':''}<tr class="stat-print" style="--stripe:${rowColors[row]};--wash:${rowWash[row]}"><th scope="row">${name}</th>${Array.from({length:11},(_,n)=>growthCell(c,row,n)).join('')}</tr>`).join('')}</tbody></table></div></div><div class="replica-footer growth-footer"><span>${C.race(c.race).name} · 成长卡</span></div>`;}
function skillView(c){const p=C.path(c.path);
 return `${replicaToolbar()}<div class="path-heading"><img src="art/${p.id}-symbol.png" alt=""><b>${p.name}</b>${btn('equipmentSkills','装备 '+Object.values(c.skills).filter(v=>v.equipped).length+'/5','small','data-equip-label')}</div><div class="skill-board" data-path="${p.id}"><svg class="skill-arrows" aria-hidden="true"></svg><div class="starter-skills">${p.skills.filter(sk=>sk.id<6).map(sk=>skillNode(c,p,sk)).join('')}</div><div class="branch-skills">${p.skills.filter(sk=>sk.id>=6).map(sk=>skillNode(c,p,sk)).join('')}</div></div>`;
}
function skillNode(c,p,sk){const st=c.skills[sk.id]||{},locked=C.prerequisites(c,sk.id).some(n=>!c.skills[n]?.learned);return `<section class="replica-skill" data-node="${sk.id}" data-learned="${!!st.learned}"><button class="skill-title" data-action="skillInfo" data-skill="${sk.id}" style="background:${CardLayout.background(p.id,sk.id)}">${esc(sk.name)}</button><span class="skill-code">${p.prefix}-${sk.id}</span>${[['learned','习得'],['mastered','掌握']].map(([key,name])=>`<button class="tree-square ${st[key]?'on':''} ${locked&&!st[key]?'is-locked':''}" role="checkbox" aria-checked="${!!st[key]}" aria-label="${sk.name} ${name}" data-action="skillCheck" data-skill="${sk.id}" data-key="${key}"><span>${name}</span>${paperCheck(st[key])}</button>`).join('')}</section>`;}
function drawArrows(){const board=$('.skill-board');if(!board)return;const box=board.getBoundingClientRect(),svg=board.querySelector('svg');svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);svg.innerHTML='<defs><marker id="skill-arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0 5 2.5 0 5Z" fill="currentColor"/></marker></defs>'+(SKILL_EDGES[board.dataset.path]||[]).map(([a,b])=>{const x=board.querySelector(`[data-node="${a}"]`).getBoundingClientRect(),y=board.querySelector(`[data-node="${b}"]`).getBoundingClientRect(),dx=Math.sign(y.left-x.left),dy=Math.sign(y.top-x.top);let sx=x.left+(dx>0?x.width:dx<0?0:x.width/2),sy=x.top+(dy>0?x.height:dy<0?0:x.height/2),tx=y.left+(dx>0?0:dx<0?y.width:y.width/2),ty=y.top+(dy>0?0:dy<0?y.height:y.height/2);return `<path d="M${sx-box.left+dx*3} ${sy-box.top+dy*3} L${tx-box.left-dx*5} ${ty-box.top-dy*5}" marker-end="url(#skill-arrow)"/>`;}).join('');}
window.addEventListener('resize',drawArrows);

function characters(){
 const c=active();if(!c)return `<section class="welcome"><div class="welcome-art"><img src="art/human0.jpg" alt=""><img src="art/elf1.jpg" alt=""><img src="art/orc0.jpg" alt=""></div><h1>让旅途，轻松一些。</h1>${btn('newCharacter','创建角色','primary wide')}</section>`;
 const r=C.race(c.race),p=C.path(c.path),v=C.cardDerived(c),defaultName=c.name===r.name+' · '+p.name||c.name===r.name;
 const accent={human:'#346B85',elf:'#287F76',halfling:'#567936',dwarf:'#576378',moon:'#704A87',orc:'#95463F',cat:'#787522',stone:'#956329',crimson:'#91447D'}[c.race];
 return `<div class="character-page" style="--role:${accent}"><h1 class="character-title">${subtab==='skills'?'技能树':'角色'}</h1><section class="traveler ${subtab==='skills'?'compact-hero':''}"><button class="hero-select" data-action="roster" aria-label="切换或新增角色"></button><img class="traveler-art" src="art/${c.race}${c.portrait}.jpg" alt=""><div class="traveler-copy"><h2 ${defaultName?'':'data-user-text'}>${esc(defaultName?r.name:c.name)}</h2><div class="traveler-race-level"><small>${r.name}</small><span class="traveler-level">等级 <b data-live-level>${v.level}</b></span></div><button class="path-select-row" data-action="choosePath"><img class="camp-path-symbol" src="art/${c.path}-symbol.png" alt=""><b>${p.name}</b>${icon('arrow')}</button></div></section><div class="camp-character-tab-row"><div class="record-tabs"><button data-action="subtab" data-tab="growth" aria-pressed="${subtab!=='skills'}">${icon('book')}成长卡</button><button data-action="subtab" data-tab="skills" aria-pressed="${subtab==='skills'}">${icon('compass')}技能树</button></div>${btn('pocket',icon('bag')+'物品','small')}</div><div id="character-record">${subtab==='skills'?skillView(c):growthView(c)}</div></div>`;
}

function refreshInk(){const c=active(),s=C.sheet(c);document.querySelectorAll('[data-action="cardMark"],[data-action="skillCheck"]').forEach(el=>{const on=el.dataset.action==='cardMark'?(+el.dataset.row===-1?s.levels[+el.dataset.col]:s.marks[+el.dataset.row][+el.dataset.col]):!!c.skills[+el.dataset.skill]?.[el.dataset.key];el.classList.toggle('on',on);if(el.dataset.action==='cardMark'){const locked=+el.dataset.col>C.cardDerived(c).level+(+el.dataset.row<0?1:0)&&!on;el.classList.toggle('is-locked',locked);el.title=locked?'达到'+el.dataset.col+'级后可提升此属性':'';}el.setAttribute('aria-checked',String(on));el.querySelector('.replica-check')?.classList.toggle('checked',on);});document.querySelectorAll('.replica-skill').forEach(el=>{const id=+el.querySelector('[data-skill]').dataset.skill;el.dataset.learned=String(!!c.skills[id]?.learned);el.dataset.mastered=String(!!c.skills[id]?.mastered);el.querySelectorAll('.tree-square').forEach(b=>b.classList.toggle('is-locked',!c.skills[id]?.[b.dataset.key]&&C.prerequisites(c,id).some(n=>!c.skills[n]?.learned)));});document.querySelectorAll('[data-live-level]').forEach(el=>el.textContent=C.cardDerived(c).level);document.querySelectorAll('[data-equip-label]').forEach(el=>el.textContent='装备 '+Object.values(c.skills).filter(s=>s.equipped).length+'/5');}
function choosePath(){const c=active();openModal('paths','选择道途',`<div class="path-options">${D.paths.map(p=>`<button data-action="setPath" data-path="${p.id}" aria-pressed="${c.path===p.id}"><img src="art/${p.id}-symbol.png" alt=""><span><b>${p.name}</b><small>${p.prefix}</small></span>${c.path===p.id?icon('check'):icon('arrow')}</button>`).join('')}</div><p class="muted path-keep-note">各道途的技能勾选分别保存，切换后可随时回来。</p>`);}

function roster(){openModal('roster','角色',`<div class="roster-list">${state.characters.map(c=>`<button data-action="pickTraveler" data-id="${esc(c.id)}"><img src="art/${c.race}${c.portrait}.jpg" alt=""><span><b data-user-text>${esc(c.name)}</b><small>${C.path(c.path).name} · 等级 ${C.cardDerived(c).level}</small></span>${c.id===active()?.id?icon('check'):icon('arrow')}</button>`).join('')}</div>`,btn('editCharacter','角色设置')+btn('newCharacter',icon('plus')+' 新角色','primary'));}
function pocket(){const c=active();openModal('pocket','物品与笔记',`<div class="pocket-counters">${[['xp','经验'],['kae','加伊']].map(([f,label])=>`<div><span>${label}</span><div>${btn('pocketCounter','−','small',`data-field="${f}" data-delta="-1" aria-label="减少${label}"`)}<b id="count-${f}">${c[f]}</b>${btn('pocketCounter','+','small',`data-field="${f}" data-delta="1" aria-label="增加${label}"`)}</div></div>`).join('')}</div><details class="resource-pocket"><summary>当前生命、法力与体力</summary><div class="resource-grid">${['生命','法力','体力'].map((name,i)=>`<div><label>${name}</label><span><b id="resource-${i}">${c.current[i]}</b> / ${C.cardDerived(c).max[i]}</span><div>${btn('pocketResource','−','small',`data-index="${i}" data-delta="-1" aria-label="减少${name}"`)}${btn('pocketResource','+','small',`data-index="${i}" data-delta="1" aria-label="增加${name}"`)}</div></div>`).join('')}</div></details><div class="field"><label for="equipment">装备与背包</label><textarea id="equipment" rows="3" maxlength="20000" placeholder="输入装备与物品">${esc(c.equipment)}</textarea></div><div class="field"><label for="char-notes">旅途笔记</label><textarea id="char-notes" rows="3" maxlength="20000" placeholder="输入角色笔记">${esc(c.notes)}</textarea></div><p class="pocket-save-note">${icon('check')} 修改后自动保存</p>`);}
function equipmentSkills(){const c=active();openModal('equipped','装备技能 · 最多 5 个',`<div class="equip-list">${C.path(c.path).skills.filter(sk=>c.skills[sk.id]?.learned).map(sk=>`<button data-action="equipDirect" data-skill="${sk.id}" aria-pressed="${!!c.skills[sk.id]?.equipped}"><span>${esc(sk.name)}</span><b>${c.skills[sk.id]?.equipped?'✓':'＋'}</b></button>`).join('')||'<p class="muted">先在技能树勾选已习得技能。</p>'}</div>`);}
function newCharacter(fresh=true){
 if(fresh)draft={name:'',race:'human',path:null,portrait:0};
 openModal('new','创建角色',`<h3 class="pick-heading first-heading">选择道途</h3><div class="path-picker">${D.paths.map(p=>`<button class="${draft.path===p.id?'selected':''}" data-action="draftPath" data-id="${p.id}" aria-pressed="${draft.path===p.id}"><img src="art/${p.id}-symbol.png" alt="">${p.name}</button>`).join('')}</div><h3 class="pick-heading">选择肖像</h3><div class="portrait-picker">${D.races.flatMap(r=>[0,1].map(i=>`<button class="portrait-pick ${draft.race===r.id&&draft.portrait===i?'selected':''}" data-action="pickPortrait" data-race="${r.id}" data-portrait="${i}" aria-label="${r.name}肖像${i+1}" aria-pressed="${draft.race===r.id&&draft.portrait===i}"><img src="art/${r.id}${i}.jpg" alt=""><span>${r.name}</span></button>`)).join('')}</div><details class="name-optional"><summary>角色名字（选填）</summary><input id="new-name" maxlength="40" value="${esc(draft.name)}" placeholder="留空使用种族与道途命名"></details>`,btn('createCharacter',draft.path?'创建角色':'请先选择道途','primary wide',draft.path?'':'disabled'));
}

function musicBadge(id,cls=''){return id<6?`<img class="music-badge ${cls}" src="art/music-${id}.png" alt="规则音乐${id}">`:`<span class="theme-badge ${cls}">${icon('music')}</span>`;}
function paintSeek(value,max){const p=Math.max(0,Math.min(1,Number(value)/(Number(max)||1)));const w=$('.wave-seek');if(w){w.style.setProperty('--seek-end',`calc(${p*100}% + ${6.5-13*p}px)`);$('.wave-clip').style.width=`calc(${p*100}% - ${13*p}px)`;}}
function paintVolume(){const el=$('#music-volume');if(el){const p=Math.max(0,Math.min(1,Number(el.value)));el.style.setProperty('--volume-end',`calc(${p*100}% + ${8.5-17*p}px)`);}}
function musicPage(){const t=Music.tracks.find(t=>t.id===(Music.get().id||1));return `<section class="music-scene"><div class="music-intro"><h1>游戏音乐</h1><p>按卡牌上的音乐编号播放。</p></div><div class="forest-art" aria-hidden="true"></div><div class="music-plate"><div class="player-song"><span id="player-badge">${musicBadge(t.id)}</span><span><b id="music-current-title">${t.name}</b><small id="music-current-en">${UI.get().language==='en'?'Kirk Hamilton':t.en}</small></span></div><div class="wave-seek"><div class="seek-base"></div><div class="wave-clip"><div class="wave-pattern"></div></div><input type="range" id="music-seek" aria-label="音乐播放进度" min="0" max="1" value="0" step=".1" disabled></div><div class="time-labels"><span id="music-elapsed">0:00</span><span id="music-duration">0:00</span></div><div class="transport"><button data-action="musicLoop" id="music-loop" aria-label="单曲循环" aria-pressed="true">${icon('repeat')}</button><button data-action="musicPrevious" aria-label="上一首">❮</button><button data-action="musicToggle" id="music-toggle" class="player-toggle" aria-label="播放音乐">${icon('play')}</button><button data-action="musicNext" aria-label="下一首">❯</button><button data-action="musicOptions" aria-label="更多播放选项">⋮</button></div></div></section><h2 class="tracks-title">曲目</h2><div class="track-list">${Music.tracks.map(t=>`<button class="track" data-action="playTrack" data-track="${t.id}">${musicBadge(t.id)}<span class="track-copy"><b>${t.name}</b><small>${UI.get().language==='en'?'Kirk Hamilton':t.en}</small></span><span class="track-indicator">${icon('play')}</span></button>`).join('')}</div><div class="music-detail"><label class="volume-line">${icon('volume')}<input type="range" id="music-volume" aria-label="音乐音量" min="0" max="1" step=".05" value="${Music.get().volume}"></label><p id="music-error" role="status"></p></div>`;}

function timeLabel(n){n=Math.max(0,Math.floor(n||0));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function updateMusic(){
 const s=Music.get(),t=Music.tracks.find(t=>t.id===s.id),mini=$('#mini-player');
 if(mini){mini.hidden=!t||page==='music';document.body.classList.toggle('has-music',!!t&&page!=='music');if(t){const key=t.id+':'+s.playing+':'+s.loading;if(mini.dataset.state!==key){mini.dataset.state=key;mini.innerHTML=`<button class="mini-open" data-action="navigate" data-page="music">${musicBadge(t.id)}<span><b>${t.name}</b><small>${s.loading?'正在载入…':s.playing?'正在播放':'已暂停'}</small></span></button><button class="mini-toggle icon-button" data-action="musicToggle" aria-label="${s.playing?'暂停音乐':'继续播放'}">${icon(s.playing?'pause':'play')}</button><button class="icon-button mini-stop" data-action="musicStop" aria-label="停止音乐">${icon('stop')}</button>`;}}}
 document.querySelectorAll('.track').forEach(el=>{const chosen=+el.dataset.track===(s.id||1);el.hidden=chosen;el.classList.toggle('playing',chosen&&s.playing);el.classList.toggle('selected-track',chosen);const isPlaying=chosen&&s.playing;el.setAttribute('aria-pressed',String(isPlaying));const indicator=el.querySelector('.track-indicator');const value=isPlaying?'pause':'play';if(indicator.dataset.icon!==value){indicator.dataset.icon=value;indicator.innerHTML=icon(value);}});
 if($('#music-current-title')){const track=t||Music.tracks[0];$('#music-current-title').textContent=track.name;$('#music-current-en').textContent=UI.get().language==='en'?'Kirk Hamilton':track.en;$('#player-badge').innerHTML=musicBadge(track.id);$('#music-toggle').innerHTML=icon(s.playing?'pause':'play');$('#music-toggle').setAttribute('aria-label',UI.tr(s.playing?'暂停音乐':'播放音乐'));$('.wave-seek').classList.toggle('is-playing',s.playing);const seek=$('#music-seek');seek.max=s.duration||1;if(!seeking)seek.value=s.position;paintSeek(seek.value,seek.max);seek.disabled=!s.duration;$('#music-elapsed').textContent=timeLabel(s.position);$('#music-duration').textContent=timeLabel(s.duration);$('#music-loop').setAttribute('aria-pressed',String(s.loop));$('#music-error').textContent=s.error||'';if(document.activeElement!==$('#music-volume'))$('#music-volume').value=s.volume;paintVolume();}
}
window.addEventListener('musicstate',updateMusic);

function searchPage(){
 if(detail)return detailPage();
 return top('冒险索引','支持中文、英文编号检索。',btn('toggleBookmarks',icon('star'),onlyBookmarks?'primary small':'small','aria-label="只看收藏"'))+`<div class="searchbox">${icon('search')}<input id="search-input" type="search" value="${esc(query)}" autocomplete="off" placeholder="如：互动1 / POI-1" aria-label="搜索索引"><button data-action="clearSearch" aria-label="清空搜索">×</button></div><div class="chips">${[['','全部'],...Object.entries(D.categories)].map(([id,n])=>`<button class="chip ${category===id?'active':''}" data-action="category" data-category="${id}">${n}</button>`).join('')}</div><div class="filter-summary"><span>${icon('shield')} ${!state.prefs.titles&&!state.prefs.after?'防剧透已开启':'自定义揭示'}${onlyBookmarks?' · 仅收藏':''}</span>${btn('filters',icon('settings')+' 设置','small')}</div><div id="results"></div>`;
}
function renderResults(){const el=$('#results');if(!el)return;
 if(!query&&!category&&!onlyBookmarks){el.innerHTML=`<div class="empty">${icon('compass')}<p>点击示例即可检索。</p><div class="toolbar">${['POI-1','EVT-1','KEY-24'].map(id=>btn('query',C.display(id),'small',`data-id="${id}"`)).join('')}</div></div>${state.recent.length?'<div class="section-title"><h2>最近查阅</h2>'+btn('clearRecent','清除','small')+'</div>'+state.recent.map(id=>result(C.resolve(id))).join(''):''}<div class="notice">可检索卡牌、地图、板块与称号。基础 A 面通常省略后缀。前置关联可能是同时要求，也可能是不同路线，请以实体卡指示为准。</div>`;return;}
 const found=C.search(query,{stage:state.prefs.stage,category,bookmarks:onlyBookmarks?state.bookmarks:null});
 el.innerHTML=`<div class="count-line">${onlyBookmarks?'我的收藏 · ':''}${found.length} 条结果${query?' · “'+esc(query)+'”':''}</div>`+(found.length?found.slice(0,limit).map(result).join('')+(found.length>limit?btn('more','继续显示结果','wide'):''):`<div class="empty">${icon('search')}<h3>未找到匹配线索</h3><p>检查编号或分类。<br>部分卡牌可能尚未收录。</p>${btn('resetFilters','清除分类与收藏筛选','small')}</div>`);
}
function result(r){if(!r)return '';return `<button class="result" data-action="openRecord" data-id="${esc(r.id)}"><span class="result-icon">${icon(r.id.startsWith('SQL')?'star':r.id.startsWith('HEX')?'map':'book')}</span><span class="result-main"><h3>${esc(C.display(r.id))}${state.bookmarks.includes(r.id)?' ☆':''}</h3><p ${state.prefs.titles?'data-record-text':''}>${state.prefs.titles?esc(UI.get().language==='en'?(r.en||r.zh):r.zh):'标题已隐藏'}${state.prefs.locations&&r.hex?' · '+esc(r.hex):''}</p></span><span class="chevron">${icon('arrow')}</span></button>`;}
function visible(key){return state.prefs.indexRevealAll|| state.prefs[key]||revealed.has(key);}
function reveal(key,title,content,note='可能包含剧透，点击显示') {return visible(key)?content:`<button class="reveal" data-action="reveal" data-key="${key}">${icon('lock')}<span><b>${title}</b><small>${note}</small></span><span style="margin-left:auto">${icon('eye')}</span></button>`;}
function refs(s){const pattern=new RegExp(D.records.map(r=>r.id).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+'|\\bHEX-[A-Z0-9]+(?: \\*)?','gi');let last=0,out='',m;while((m=pattern.exec(s))){out+=esc(C.display(s.slice(last,m.index)));const record=C.resolve(m[0]);out+=`<button class="ref" data-action="openRecord" data-id="${esc(m[0])}">${esc(C.display(m[0]))}</button>`;last=m.index+m[0].length;}return out+esc(C.display(s.slice(last)));}
function detailPage(){
 const r=C.resolve(detail)||{id:detail,zh:'此编号尚无说明',en:'',hex:'',map:'',stage:0,hint:'',rows:[]};
 const before=C.relationships(r.id,'before',state.prefs.startOnly),after=C.relationships(r.id,'after');
 return `${btn('backSearch',icon('back')+' 返回检索','small back-btn')}<div class="detail-hero"><div class="detail-code">${esc(C.display(r.id))} <span style="opacity:.6"> / ${esc(r.id)}</span></div>${visible('titles')?`<h2 data-record-text>${esc(UI.get().language==='en'?(r.en||r.zh):r.zh)}</h2><p>${esc(r.en)}</p>`:'<h2>标题已隐藏</h2>'+btn('reveal',icon('eye')+' 显示标题','small','data-key="titles"')}<div class="row" style="margin-top:12px">${C.resolve(detail)?btn('bookmark',icon('star')+(state.bookmarks.includes(r.id)?' 已收藏':' 收藏'),'small',`data-id="${esc(r.id)}"`):''}</div></div><div class="section-title"><h2>卡牌正文</h2></div><div class="panel"><p class="muted">按提供的中文卡牌资料查阅完整正文。</p><button class="btn primary wide" data-camp="reference" data-reference="${esc(r.id)}">查看卡牌正文</button></div><div class="section-title"><h2>出现地点</h2>${icon('map')}</div>${reveal('locations','揭示位置',`<div class="panel"><p class="body-copy">${r.hex?refs('HEX-'+r.hex.replace(/\//g,' / HEX-')):'未标注固定地块'}</p>${r.map?'<p class="body-copy">关联地图：'+refs(r.map)+'</p>':''}</div>`)}<div class="section-title"><h2>${/^(SQL|TBL)-/.test(r.id)&&state.prefs.startOnly?'从哪里开始':'前置关联'}</h2></div>${reveal('before','查看前置线索',`<div class="panel">${before.length?before.map(s=>`<div class="link-row">${refs(s)}</div>`).join(''):'<p class="muted">暂无前置关联。</p>'}</div>`)}<div class="section-title"><h2>后续关联</h2></div>${reveal('after','查看后续线索',`<div class="panel">${after.length?after.map(s=>`<div class="link-row">${refs(s)}</div>`).join(''):'<p class="muted">暂无后续关联。</p>'}</div>`)}${r.hint?`<div class="section-title"><h2>梓昆币提示</h2></div>${reveal('hints','展开完整提示',`<div class="panel body-copy" data-record-text>${esc(UI.get().language==='en'?(r.hintEn||r.hint):r.hint)}</div>`,'含明确剧透，建议先尝试前置线索')}`:''}<div class="notice">多个前置关联可能代表并列条件或不同路线，请以卡牌正文为准。</div>`;
}
function ownedSquills(){return state.squills.length?`<div class="owned-coins">${[...state.squills].sort((a,b)=>a-b).map(n=>`<span class="coin-wrap"><button class="owned-coin" data-action="openRecord" data-id="SQL-${n}" aria-label="查看梓昆币 ${n}">${n}</button><button class="coin-remove" data-action="removeCoin" data-number="${n}" aria-label="移除梓昆币 ${n}">×</button></span>`).join('')}</div><p class="muted owned-help">点击编号旁的 × 可移除记录</p>`:'<p class="squill-empty">还没有记录。获得后，在这里添加编号。</p>';}

function refreshSquills(message){$('#owned-squills').innerHTML=ownedSquills();$('#squill-feedback').textContent=message;}
function settings(){return top('设置','')+preferencesPanel()+`<div class="two-cols camp-setting-tools">${btn('navigate',icon('music')+' 游戏音乐','','data-page="music"')}<button class="btn" data-camp="icons">${icon('book')} 图标说明</button></div><div class="section-title"><h2>队伍笔记</h2></div><div class="panel"><textarea id="party-notes" rows="5" maxlength="50000" placeholder="记录线索与下次出发的计划…">${esc(state.notes)}</textarea>${btn('savePartyNotes','保存旅程笔记','primary wide')}</div><div class="section-title"><h2>存档与备份</h2></div><div class="panel"><p class="muted">角色、技能、背包、垂钓日志与网页地图记录保存在本机。换设备或清理网站数据前，请导出备份。</p><div class="two-cols">${btn('backup',icon('download')+' 导出备份','primary')}${btn('importBackup',icon('save')+' 导入备份')}</div></div><div class="section-title"><h2>关于旅伴</h2></div><section class="panel about-panel support-panel"><div class="about-heading"><h3>阿瑞迪亚 · 旅伴</h3><span class="about-version">3.9.1 · 网页版</span></div><button class="btn" data-camp="updates">更新公告</button><p class="app-notice">卡牌文本经手工初步校对，仍可能有错误，请以实体卡牌和说明书为准。有问题可在交流群反馈。</p><p class="muted">交流群：328669965</p><p class="creator-credit">设计与制作 <strong>IzumiSaito</strong></p>${btn('showIntro','重看开场卡','quiet intro-replay')}<h3>免费使用，自愿支持</h3><p>本软件由个人开发和维护，所有功能完全免费。欢迎自愿打赏支持，是否赞助都不影响正常使用。</p>${supportButtons()}</section>`;}

const mapModalStack=[];let mapModalFrame=null,mapHistory=false,skipMapPop=false;
function releaseMapHistory(){if(mapHistory){mapHistory=false;skipMapPop=true;history.back();}}
addEventListener('popstate',()=>{if(skipMapPop){skipMapPop=false;return;}if(!mapHistory)return;mapHistory=false;if(mapModalStack.length)restoreMapParent();else closeModal();});
function rememberMapFrame(){if(!mapModalFrame)return;const box=$('#modal-root');mapModalFrame.fields=[...box.querySelectorAll('input,textarea,select')].map((e,index)=>({id:e.id,index,value:e.value,checked:e.checked}));mapModalFrame.scroll=box.querySelector('.modal-body')?.scrollTop||0;}
function restoreMapParent(){const previous=mapModalStack.pop();if(!previous)return false;openModal(...previous.args,true);for(const field of previous.fields||[]){const e=field.id?document.getElementById(field.id):$('#modal-root').querySelectorAll('input,textarea,select')[field.index];if(e){e.value=field.value;e.checked=field.checked;}}const content=$('#modal-root .modal-body');if(content)content.scrollTop=previous.scroll||0;return true;}
function openModal(type,title,body,actions='',detached='',restoring=false){
 const same=modal===type;
 const isMap=t=>t==='campaignMapMenu'||t==='campaignMapSaves'||t==='campaignMapSaveName'||t==='campaignMapSaveDelete'||t==='campaignMapProgress'||t==='campaignMapRoom'||t==='campaignMapFreeWarning'||t==='campaignMapReset'||t==='campaignMapGuide'||t==='campaignMapNote';
 if(!restoring){if(isMap(type)&&isMap(modal)&&type!==modal&&mapModalFrame){rememberMapFrame();if(type==='campaignMapSaves'&&mapModalStack.some(x=>x.args[0]===type)){while(mapModalStack.length&&mapModalStack.at(-1).args[0]!==type)mapModalStack.pop();mapModalStack.pop();}else mapModalStack.push(mapModalFrame);}else if(!isMap(type)||!isMap(modal)){mapModalStack.length=0;}}
 if(isMap(type)&&!mapHistory){history.pushState({arydiaMapSheet:true},'');mapHistory=true;}else if(!isMap(type))releaseMapHistory();
 modal=type;mapModalFrame=isMap(type)?{args:[type,title,body,actions,detached]}:null;
 const titleElement=document.createElement('div');titleElement.innerHTML=title;titleElement.querySelectorAll('button').forEach(b=>b.remove());const accessibleTitle=esc(titleElement.textContent||'');
 const paper=`<section class="modal" data-kind="${esc(type)}" ${detached?'role="document"':`role="dialog" aria-modal="true" aria-label="${accessibleTitle}"`}><div class="modal-head">${mapModalStack.length?'<button class="modal-back" data-action="backModal" aria-label="返回上一级">'+icon('back')+'</button>':''}<h2>${title}</h2>${type.startsWith('welcome')?'':'<button class="close" data-action="closeModal" aria-label="关闭">×</button>'}</div><div class="modal-body">${body}<div class="form-error" id="form-error" role="alert"></div></div>${actions?'<div class="modal-actions">'+actions+'</div>':''}</section>`;
 $('#modal-root').innerHTML=`<div class="modal-overlay">${detached?`<div class="modal-pair" role="dialog" aria-modal="true" aria-label="${accessibleTitle}">${paper}${detached}</div>`:paper}</div>`;
 document.body.style.overflow='hidden';UI.localize();requestAnimationFrame(()=>$('.modal button')?.focus({preventScroll:true}));
}
function closeModal(){if(modal.startsWith('welcome'))return;if(mapModalStack.length&&restoreMapParent())return;mapModalFrame=null;mapModalStack.length=0;releaseMapHistory();const campaign=modal==='support'?campaignSupportOrigin:'';campaignSupportOrigin='';const resume=modal==='support'&&supportFromWelcome;supportFromWelcome=false;modal='';$('#modal-root').innerHTML='';document.body.style.overflow='';if(campaign)Campaign.updates(campaign==='welcomeCampaignUpdate');else if(resume)welcomeAbout();}
function formError(s){if($('#form-error'))$('#form-error').textContent=s;else toast(s);}

function filters(){const names={indexRevealAll:['全部展开（涉及剧透）','显示标题、地点和前后关联'],titles:['显示条目标题','包含中文标题与英文原名'],locations:['显示地点','包含地块与地图编号'],before:['显示前置关联','可能揭示获得物品或触发事件的方式'],after:['显示后续关联','可能揭示后续剧情'],startOnly:['梓昆币／石板仅显示起点','只显示最初的前置线索']};openModal('filters','检索设置',`${Object.entries(names).map(([k,[name,desc]])=>`<div class="setting-row"><div><b>${name}</b><small>${desc}</small></div><button role="switch" aria-checked="${state.prefs[k]}" aria-label="${name}" class="switch ${state.prefs[k]?'on':''}" data-action="pref" data-key="${k}"></button></div>`).join('')}<p class="muted" style="margin-top:15px">梓昆币的完整提示始终单独揭示。</p>`,btn('resetSpoilers','恢复防剧透')+btn('closeModal','完成','primary'));}
function backup(raw=false){try{const contents=raw?(window.Android?Android.load():localStorage.getItem('arydia-v1')):JSON.stringify(state,null,2);if(window.Android)Android.exportBackup(contents||'');else window.WebApp.exportBackup(contents||'');}catch(e){toast('无法导出：'+e.message);}}
window.receiveBackup=function(text){try{const incoming=C.validate(JSON.parse(text));draft={incoming};openModal('import','导入旅程备份',`<p>备份包含 <b>${incoming.characters.length}</b> 个角色、<b>${incoming.bookmarks.length}</b> 个收藏、<b>${incoming.squills.length}</b> 枚梓昆币记录。</p><div class="notice">导入会替换当前所有记录。建议先导出当前备份。只有确认后才会替换。</div>`,btn('backup','先备份当前记录')+btn('confirmImport','确认替换','primary'));}catch(e){toast('导入失败：'+e.message);}};
window.nativeStatus=msg=>toast(msg);
window.appBack=function(){if(modal){closeModal();return true;}if(detail){detail=null;render();return true;}if(page!=='characters'){page='characters';render();return true;}return false;};
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,c=active();
 if(a==='uiSection'){settingsSection=settingsSection===b.dataset.section?'':b.dataset.section;render();}
 else if(a==='backModal')restoreMapParent();
 else if(a==='uiChoice'){try{UI.set({[b.dataset.key]:b.dataset.key==='scale'?Number(b.dataset.value):b.dataset.value});settingsSection=b.dataset.key==='scale'?'':'appearance';render();}catch(err){toast('保存失败');}}
 else if(a==='capPicker'){openModal('cap','公会等级上限',`<div class="cap-grid">${Array.from({length:10},(_,i)=>btn('setCap',(i+1)+' 级',state.prefs.cap===i+1?'primary':'',`data-cap="${i+1}"`)).join('')}</div>`);}
 else if(a==='setCap'){if(change(()=>state.prefs.cap=Number(b.dataset.cap)))closeModal();}
 else if(a==='clearRecent')change(()=>state.recent=[]);
 else if(a==='skillInfo'){const p=C.path(c.path),sk=p.skills.find(sk=>sk.id===Number(b.dataset.skill)),required=C.prerequisites(c,sk.id);openModal('skillInfo',esc(sk.name),`<p class="muted">${p.prefix}-${sk.id}</p><h3>先决技能</h3>${required.length?required.map(n=>`<p>${c.skills[n]?.learned?'✓':'○'} ${esc(p.skills.find(sk=>sk.id===n).name)} · ${p.prefix}-${n}</p>`).join(''):'<p>没有先决技能</p>'}<p class="muted">需要先学会所有先决技能，无需先掌握或装备。</p>`);}
 else if(a==='musicPrevious'||a==='musicNext'){const id=Music.get().id||1;Music.command('play',(id-1+(a==='musicNext'?1:5))%6+1);}
 else if(a==='musicOptions'){openModal('musicOptions','播放选项',btn('musicStop','停止播放','wide'));}
 else if(a==='welcomeLanguageChoice'){welcomeLanguage=b.dataset.value;document.querySelectorAll('[data-action="welcomeLanguageChoice"]').forEach(el=>el.classList.toggle('primary',el.dataset.value===welcomeLanguage));}
 else if(a==='welcomeLanguageDone'){try{UI.set({language:welcomeLanguage,skipLanguage:$('#welcome-skip').checked});modal='';closeModal();render();welcomeAbout();}catch(err){formError('保存失败');}}
 else if(a==='welcomeAboutDone'){try{UI.set({skipAbout:$('#welcome-skip').checked});modal='';closeModal();if(!Intro.accepted())Intro.show();}catch(err){formError('保存失败');}}
 else if(a==='navigate'){settingsSection='';if(page===b.dataset.page&&!detail)return;page=b.dataset.page;detail=null;render();window.scrollTo(0,0);}
 else if(a==='newCharacter'){if(state.characters.length>=40)return toast('最多保存40个角色');newCharacter();}
 else if(a==='draftPath'){draft.path=b.dataset.id;document.querySelectorAll('[data-action="draftPath"]').forEach(el=>{const on=el.dataset.id===draft.path;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));});const create=$('[data-action="createCharacter"]');create.disabled=false;create.textContent='创建角色';}
 else if(a==='createCharacter'){if(!draft.path)return formError('请选择道途');try{const n=C.create($('#new-name')?.value.trim()||C.race(draft.race).name+' · '+C.path(draft.path).name,draft.race,draft.path,draft.portrait);if(change(()=>{C.sheet(n);state.characters.push(n);state.active=n.id;})){closeModal();toast('角色已创建');}}catch(err){formError(err.message);}}
 else if(a==='selectCharacter')change(()=>state.active=b.dataset.id);
 else if(a==='roster')roster();
 else if(a==='pickTraveler'){if(change(()=>state.active=b.dataset.id)){closeModal();}}
 else if(a==='pocket')pocket();
 else if(a==='pocketResource'){const i=+b.dataset.index;if(change(()=>c.current[i]=Math.max(0,Math.min(C.cardDerived(c).max[i],c.current[i]+Number(b.dataset.delta))),false))$('#resource-'+i).textContent=c.current[i];}
 else if(a==='pocketCounter'){const f=b.dataset.field;if(change(()=>c[f]=Math.max(0,Math.min(999999,c[f]+Number(b.dataset.delta))),false))$('#count-'+f).textContent=c[f];}
 else if(a==='equipmentSkills')equipmentSkills();
 else if(a==='equipDirect'){if(change(()=>C.toggleSkill(c,+b.dataset.skill,'equipped'),false)){refreshInk();equipmentSkills();}}
 else if(a==='pickPortrait'){draft.race=b.dataset.race;draft.portrait=+b.dataset.portrait;document.querySelectorAll('[data-action="pickPortrait"]').forEach(el=>{const on=el.dataset.race===draft.race&&+el.dataset.portrait===draft.portrait;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));});}
 else if(a==='choosePath')choosePath();
 else if(a==='setPath'){if(change(()=>C.switchPath(c,b.dataset.path))){closeModal();}}
 else if(a==='support'){campaignSupportOrigin=['welcomeCampaignUpdate','campaignUpdate'].includes(modal)?modal:'';supportFromWelcome=modal==='welcomeAbout';const method=b.dataset.method==='alipay'?'alipay':'wechat',file=method==='alipay'?'alipay.jpg':'wechat.png';openModal('support','支持 IzumiSaito',`<p class="muted">感谢你支持旅伴的制作与持续完善。</p><img class="support-code" src="support/${file}" alt="${method==='alipay'?'支付宝':'微信'}收款码">`,btn('saveSupport','保存收款码','primary',`data-method="${method}"`));}
 else if(a==='saveSupport'){const method=b.dataset.method==='alipay'?'alipay':'wechat';if(window.Android?.saveSupportImage)Android.saveSupportImage(method);else{const a=document.createElement('a');a.href='support/'+(method==='alipay'?'alipay.jpg':'wechat.png');a.download='IzumiSaito-'+method+(method==='alipay'?'.jpg':'.png');a.click();}}
 else if(a==='playTrack'){const id=+b.dataset.track,s=Music.get();Music.command(s.id===id&&s.playing?'pause':'play',id);}
 else if(a==='musicToggle'){const s=Music.get();Music.command(s.playing?'pause':'play',s.id||1);}
 else if(a==='musicStop')Music.command('stop');
 else if(a==='musicLoop')Music.command('loop',Music.get().loop?0:1);
 else if(a==='subtab'){if(subtab===b.dataset.tab)return;subtab=b.dataset.tab;document.querySelectorAll('[data-action="subtab"]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.tab===subtab)));$('#character-record').innerHTML=subtab==='skills'?skillView(c):growthView(c);UI.localize();requestAnimationFrame(()=>{document.documentElement.style.setProperty('--app-nav-height',$('#nav').getBoundingClientRect().height+'px');syncHeroContour();drawArrows();});}
 else if(a==='showIntro')window.Intro?.show();
 else if(a==='closeModal')closeModal();
 else if(a==='cardMark'){if(change(()=>C.toggleMark(c,+b.dataset.row,+b.dataset.col),false)){refreshInk();clearTimeout(timer);$('#toast').classList.remove('show');$('#toast').textContent='';}}

 else if(a==='skillCheck'){if(change(()=>C.toggleSkill(c,+b.dataset.skill,b.dataset.key),false))refreshInk();}
 else if(a==='counter')change(()=>{const f=b.dataset.field;c[f]=Math.max(0,Math.min(999999,c[f]+Number(b.dataset.delta)));});
 else if(a==='resource')change(()=>{const i=+b.dataset.index;c.current[i]=Math.max(0,Math.min(C.cardDerived(c).max[i],c.current[i]+Number(b.dataset.delta)));});
 else if(a==='restore'){openModal('restore','恢复全部状态','<p>将当前角色的生命、法力与体力恢复到各自上限。请先按实体卡完成休息或恢复效果。</p>',btn('closeModal','取消')+btn('confirmRestore','确认恢复','primary'));}
 else if(a==='confirmRestore'){if(change(()=>c.current=C.cardDerived(c).max)){closeModal();toast('状态已恢复');}}
 else if(a==='saveNotes'){const eq=$('#equipment').value,nt=$('#char-notes').value;if(change(()=>{c.equipment=eq;c.notes=nt;},false))toast('角色手记已保存');}
 else if(a==='savePartyNotes'){const text=$('#party-notes').value;if(change(()=>state.notes=text,false))toast('旅程笔记已保存');}
 else if(a==='editCharacter'){openModal('edit','编辑角色',`<div class="field"><label for="edit-name">名字</label><input id="edit-name" maxlength="40" value="${esc(c.name)}"></div><div class="two-cols"><div class="field"><label for="edit-title">称号</label><input id="edit-title" maxlength="100" value="${esc(c.title)}"></div><div class="field"><label for="edit-rank">道途层次</label><input id="edit-rank" maxlength="100" value="${esc(c.rank)}"></div></div><p class="muted">道途可在角色页切换，各道途技能分别保存。</p><div class="spacer"></div>${btn('deleteCharacter','删除这个角色','danger small')}`,btn('closeModal','取消')+btn('confirmEdit','保存','primary'));}
 else if(a==='confirmEdit'){const name=$('#edit-name').value.trim(),title=$('#edit-title').value,rank=$('#edit-rank').value;if(!name)return formError('角色名字不能为空');if(change(()=>{c.name=name;c.title=title;c.rank=rank;}))closeModal();}
 else if(a==='deleteCharacter'){openModal('delete','删除角色',`<p>删除“${esc(c.name)}”及其全部成长、技能和笔记。</p><div class="notice">此操作无法撤销，可先导出备份。</div>`,btn('closeModal','保留角色')+btn('confirmDelete','确认删除','danger'));}
 else if(a==='confirmDelete'){if(change(()=>{state.characters=state.characters.filter(x=>x.id!==c.id);state.active=state.characters[0]?.id||null;}))closeModal();}
 else if(a==='viewImage'){const im=b.dataset.image;if(!/^[a-z]+-(front|back)$/.test(im))return;openModal('image','原始卡面',`<p class="muted">轻触图片切换放大；放大后可滑动查看。</p><div class="spacer"></div><div class="image-scroll"><img class="full-image" data-action="zoomImage" src="art/${im}.jpg" alt="角色或道途原始卡面"></div>`);}
 else if(a==='zoomImage')b.classList.toggle('zoomed');
 else if(a==='category'){category=b.dataset.category;limit=60;render();}
 else if(a==='clearSearch'){query='';limit=60;$('#search-input').value='';renderResults();$('#search-input').focus();}
 else if(a==='toggleBookmarks'){onlyBookmarks=!onlyBookmarks;render();}
 else if(a==='query'){query=C.display(b.dataset.id);render();}
 else if(a==='resetFilters'){category='';onlyBookmarks=false;render();}
 else if(a==='more'){limit+=60;renderResults();}
 else if(a==='openRecord'){closeModal();const r=C.resolve(b.dataset.id);page='search';detail=r?.id||b.dataset.id;revealed=new Set();if(r)change(()=>state.recent=[r.id,...state.recent.filter(x=>x!==r.id)].slice(0,15),false);render();window.scrollTo(0,0);}
 else if(a==='backSearch'){detail=null;render();window.scrollTo(0,0);}
 else if(a==='reveal'){revealed.add(b.dataset.key);const y=window.scrollY;render();window.scrollTo(0,y);}
 else if(a==='bookmark'){change(()=>{const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];});}
 else if(a==='filters')filters();
 else if(a==='pref'){change(()=>state.prefs[b.dataset.key]=!state.prefs[b.dataset.key]);const y=$('.modal').scrollTop;filters();$('.modal').scrollTop=y;}
 else if(a==='resetSpoilers'){change(()=>{Object.assign(state.prefs,{titles:false,locations:false,before:false,after:false,startOnly:true});});revealed.clear();filters();render();}
 else if(a==='removeCoin'){const n=+b.dataset.number;if(change(()=>state.squills=state.squills.filter(x=>x!==n),false))refreshSquills('已移除 '+n+' 号记录');}
 else if(a==='backup')backup();else if(a==='rawBackup')backup(true);
 else if(a==='importBackup'){if(window.Android)Android.importBackup();else $('#import-file').click();}
 else if(a==='confirmImport'){const old=C.clone(state),oldError=loadError;try{state=draft.incoming;loadError='';persist();detail=null;closeModal();render();toast('备份已恢复');}catch(err){state=old;loadError=oldError;formError('恢复失败，原记录仍保留：'+err.message);}}
});
document.addEventListener('submit',e=>{if(e.target.id!=='squill-form')return;e.preventDefault();const input=$('#squill-number'),value=input.value.trim(),n=Number(value),feedback=$('#squill-feedback');if(!/^\d+$/.test(value)||n<1||n>35){feedback.textContent='请核对并输入币面上的有效编号';input.focus();return;}if(state.squills.includes(n)){feedback.textContent=n+' 号已经记录过了';return;}if(change(()=>{state.squills.push(n);state.squills.sort((a,b)=>a-b);},false)){input.value='';refreshSquills('已记录 '+n+' 号');}});
document.addEventListener('pointerdown',e=>{if(e.target.id==='music-seek')seeking=true;});
document.addEventListener('pointerup',()=>{seeking=false;});
document.addEventListener('pointercancel',()=>{seeking=false;});
document.addEventListener('input',e=>{if(e.target.id==='music-volume'){paintVolume();Music.command('volume',Number(e.target.value));}else if(e.target.id==='music-seek'){seeking=true;$('#music-elapsed').textContent=timeLabel(Number(e.target.value));paintSeek(e.target.value,e.target.max);}else if(e.target.id==='search-input'){query=e.target.value;limit=60;renderResults();}
 // Text notes save on each edit without replacing the focused field.
 else if(e.target.id==='equipment'){const text=e.target.value;change(()=>active().equipment=text,false);}
 else if(e.target.id==='char-notes'){const text=e.target.value;change(()=>active().notes=text,false);}
 else if(e.target.id==='party-notes'){const text=e.target.value;change(()=>state.notes=text,false);}
});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='music-seek'){seeking=false;Music.command('seek',Number(e.target.value));}else if(['stage-setting','filter-stage'].includes(id)){const n=+e.target.value;revealed.clear();change(()=>state.prefs.stage=n);}
 else if(id==='cap-setting'){const n=+e.target.value;change(()=>state.prefs.cap=n);}
 else if(id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('备份文件过大，请选择5MB以内的JSON文件');e.target.value='';return;}file.text().then(window.receiveBackup).catch(()=>toast('文件读取失败'));e.target.value='';}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')window.appBack();if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select,.modal textarea')];const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.nativeInsets=function(top,right,bottom,left){const style=document.documentElement.style;[['top',top],['right',right],['bottom',bottom],['left',left]].forEach(([key,value])=>style.setProperty('--safe-'+key,Math.max(0,Number(value)||0)+'px'));};
if(window.Android?.getInsets){try{window.nativeInsets(...JSON.parse(Android.getInsets()));}catch(e){}}
window.addEventListener('storage',e=>{if(e.key==='arydia-v1'){loadError='另一个窗口更新了记录。请刷新本页后继续，避免覆盖新记录。';toast(loadError);}});

let settingsSection='',welcomeLanguage=UI.get().language,supportFromWelcome=false;
function preferencesPanel(){const p=UI.get(),dark=document.documentElement.dataset.theme==='dark',sizes=[[1,'标准'],[1.1,'较大'],[1.2,'大'],[1.3,'特大']];return `<section class="panel preferences"><h3>外观与字号</h3><div class="preference-tabs">${[['appearance','外观'],['scale','字号']].map(([key,title])=>btn('uiSection',title,settingsSection===key?'primary':'',`data-section="${key}" aria-expanded="${settingsSection===key}"`)).join('')}</div>${settingsSection==='appearance'?`<div class="setting-row"><b>深色模式</b><button class="switch ${dark?'on':''}" role="switch" aria-label="深色模式" aria-checked="${dark}" data-action="uiChoice" data-key="appearance" data-value="${dark?'light':'dark'}"></button></div><h4 class="camp-theme-label">主题色</h4><div class="preference-choices">${[['race','跟随种族'],['original','经典淡绿']].map(([v,title])=>btn('uiChoice',title,p.themeColor===v?'primary':'',`data-key="themeColor" data-value="${v}"`)).join('')}</div><p class="muted">${p.themeColor==='race'?'全局配色跟随当前角色的种族。':'使用原来的淡绿色配色。'}</p>`:settingsSection==='scale'?`<div class="preference-choices">${sizes.map(([v,title])=>btn('uiChoice',title,p.scale===v?'primary':'',`data-key="scale" data-value="${v}"`)).join('')}</div>`:''}</section>`;}

function supportButtons(){return UI.get().language==='en'?'<a class="btn kofi wide" href="https://ko-fi.com/X2G728DT8H" target="_blank" rel="noopener noreferrer">Support me on Ko-fi</a>':`<div class="two-cols">${btn('support','微信支持','primary','data-method="wechat"')}${btn('support','支付宝支持','','data-method="alipay"')}</div>`;}
function noticeText(){return UI.get().language==='en'?"This is an unofficial, fan-made companion for use with the physical game. The text has not been comprehensively proofread; only basic checks of index entries and IDs have been made. Names and descriptions may differ from the printed game. Follow your physical cards and rulebook.":'本应用为玩家制作的非官方辅助工具，需要配合实体游戏使用。目前文本尚未全面校对，仅对索引条目和编号进行了简单核对；名称、译文及描述可能与游戏文本有出入。请以实体游戏卡牌与规则书为准。';}
function welcomeAbout(){if(UI.get().skipAbout){if(!Intro.accepted())Intro.show();return;}openModal('welcomeAbout','关于这个软件',`<p class="app-notice" data-record-text>${noticeText()}</p><h3>支持旅伴的制作</h3><p class="muted">自愿支持，不影响任何功能使用。</p>${supportButtons()}${UI.get().language==='zh'?'<p class="muted">交流群：328669965</p>':''}<label class="skip-prompt"><input type="checkbox" id="welcome-skip">下次不再提醒</label>`,btn('welcomeAboutDone','继续','primary wide'));}
window.AppUI={startWelcome(){if(UI.get().skipLanguage){welcomeAbout();return;}openModal('welcomeLanguage','Language / 语言',`<div class="two-cols">${btn('welcomeLanguageChoice','简体中文',welcomeLanguage==='zh'?'primary':'','data-value="zh"')}${btn('welcomeLanguageChoice','English',welcomeLanguage==='en'?'primary':'','data-value="en"')}</div><label class="skip-prompt"><input type="checkbox" id="welcome-skip">下次不再提醒 / Don't show this again</label>`,btn('welcomeLanguageDone','继续 / Continue','primary wide'));}};

window.CampaignHost={state:()=>state,active,page:()=>page,render,icon,refs,supportButtons,toast,modal:openModal,indexFilters:filters,openIndex(id){closeModal();page='search';detail=C.resolve(id)?.id||id;revealed.clear();change(()=>state.recent=[detail,...state.recent.filter(x=>x!==detail)].slice(0,15),false);render();window.scrollTo(0,0);},
 mutate(fn,redraw=true){return change(()=>fn(state),redraw);},
 close(){mapModalStack.length=0;mapModalFrame=null;releaseMapHistory();modal='';$('#modal-root').innerHTML='';document.body.style.overflow='';},
 go(target){page=target;detail=null;revealed.clear();render();window.scrollTo({top:0,behavior:'instant'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#main').animate([{opacity:.35},{opacity:1}],{duration:220,easing:'ease-out'});}
};
Campaign.connect(window.CampaignHost);AppUI.startWelcome=()=>Campaign.startNotices();
render();
})();
